import { GenMessage } from '@bufbuild/protobuf/codegenv2';
import { Message } from '@bufbuild/protobuf';

/**
 * Request and response types for the Indexer Read Service API.
 *
 * All field names use snake_case to match the Rust serde serialization.
 * All integer fields use bigint to avoid JavaScript number precision loss
 * for large u64 values.
 */
interface BasicHealthResponse {
    status: string;
}
interface StorageHealth {
    status: string;
    connected: boolean;
}
interface DetailedHealthResponse {
    status: string;
    version: string;
    timestamp: string;
    uptime_seconds: bigint;
    storage: StorageHealth;
}
interface LivenessResponse {
    alive: boolean;
}
interface ReadinessResponse {
    ready: boolean;
    storage: boolean;
}
interface StatsResponse {
    total_utxos: bigint;
    latest_absolute_index: bigint | null;
}
interface TreeInfoResponse {
    tree_index: bigint;
    num_leaves: bigint;
    root: string;
    utxo_count: bigint;
}
interface ProofRequest {
    tree_index: bigint;
    insertion_index: bigint;
}
interface ProofResponse {
    root: string;
    tree_index: bigint;
    insertion_index: bigint;
    proof: string[];
    leaf: string;
}
interface BatchProofEntry {
    insertion_index: bigint;
    proof: string[];
    leaf: string;
}
interface BatchProofResponse {
    /** Shared Merkle root for all proofs (all generated under a single read lock). */
    root: string;
    tree_index: bigint;
    proofs: BatchProofEntry[];
}
interface UtxoRequest {
    start?: bigint;
    end?: bigint;
    limit?: bigint;
}
interface UtxoDataResponse {
    absolute_index: bigint;
    tree_index: bigint;
    insertion_index: bigint;
    final_commitment: string;
    h1_hash: string;
    h2_hash: string;
    h1_version: string;
    h1_commitment_index: string;
    h1_sender_address: string;
    h1_mint_address: string;
    h1_relayer_fixed_sol_fees: bigint;
    h1_year: bigint;
    h1_month: bigint;
    h1_day: bigint;
    h1_hour: bigint;
    h1_minute: bigint;
    h1_second: bigint;
    h1_pool_volume_spl: bigint;
    h1_pool_volume_sol: bigint;
    aes_encrypted_data: string;
    depositor_x25519_public_key: string;
    timestamp: bigint;
    slot: bigint;
    event_type: string;
}
interface UtxoResponse {
    items: UtxoDataResponse[];
    has_more: boolean;
    next_cursor: bigint | null;
    total_count: bigint;
    start_index: bigint;
    end_index: bigint | null;
}
interface UtxoColumnarColumns {
    absolute_index: bigint[];
    tree_index: bigint[];
    insertion_index: bigint[];
    final_commitment: string[];
    h1_version: string[];
    h1_commitment_index: string[];
    h1_sender_address: string[];
    h1_mint_address: string[];
    h1_relayer_fixed_sol_fees: bigint[];
    h1_year: bigint[];
    h1_month: bigint[];
    h1_day: bigint[];
    h1_hour: bigint[];
    h1_minute: bigint[];
    h1_second: bigint[];
    h1_pool_volume_spl: bigint[];
    h1_pool_volume_sol: bigint[];
    h1_hash: string[];
    h2_hash: string[];
    aes_encrypted_data: string[];
    depositor_x25519_public_key: string[];
    timestamp: bigint[];
    slot: bigint[];
    event_type: string[];
}
interface UtxoColumnarResponse {
    columns: UtxoColumnarColumns | null;
    count: bigint;
    has_more: boolean;
    next_cursor: bigint | null;
    total_count: bigint;
    start_index: bigint;
    end_index: bigint | null;
}
interface ReadServiceClientConfig {
    /** Base URL of the read service (e.g. "http://localhost:8082"). */
    endpoint: string;
    /** Optional custom fetch implementation for testing. */
    fetch?: typeof globalThis.fetch;
}

/**
 * ReadServiceClient — typed HTTP client for the Umbra Indexer Read Service.
 *
 * All responses are protobuf-encoded binary.
 *
 * @example
 * ```typescript
 * const client = new ReadServiceClient({ endpoint: "http://localhost:8082" });
 * const stats = await client.getStats();
 * const proof = await client.getProof(0, 42);
 * const utxos = await client.getUtxoData({ start: 0, limit: 100 });
 * ```
 */

declare class ReadServiceClient {
    private readonly endpoint;
    private readonly fetchFn;
    constructor(config: ReadServiceClientConfig);
    health(): Promise<BasicHealthResponse>;
    healthDetailed(): Promise<DetailedHealthResponse>;
    liveness(): Promise<LivenessResponse>;
    readiness(): Promise<ReadinessResponse>;
    /** Get global UTXO statistics. */
    getStats(): Promise<StatsResponse>;
    /**
     * Get metadata for a specific Merkle tree.
     *
     * @param treeIndex - The Merkle tree index.
     */
    getTreeInfo(treeIndex: bigint): Promise<TreeInfoResponse>;
    /**
     * Get a Merkle proof for a specific leaf in a tree.
     *
     * @param treeIndex - The Merkle tree index.
     * @param insertionIndex - The leaf index within the tree.
     */
    getProof(treeIndex: bigint, insertionIndex: bigint): Promise<ProofResponse>;
    /**
     * Get Merkle proofs for multiple leaves in a single atomic request.
     *
     * All proofs are generated under a single tree read lock, guaranteeing
     * they share the same Merkle root.
     *
     * @param treeIndex - The Merkle tree index.
     * @param insertionIndices - Leaf indices within the tree (max 8).
     */
    getBatchProof(treeIndex: bigint, insertionIndices: bigint[]): Promise<BatchProofResponse>;
    /**
     * Fetch UTXO data by absolute index range with pagination.
     *
     * @param params - Query parameters (start, end, limit — all optional).
     */
    getUtxoData(params?: UtxoRequest): Promise<UtxoResponse>;
    /**
     * Fetch UTXO data in columnar layout for maximum compression.
     *
     * Sends `X-Response-Layout: columnar` header. Data is transposed into
     * column arrays instead of row arrays for better compression ratios.
     *
     * @param params - Query parameters (start, end, limit — all optional).
     */
    getUtxoDataColumnar(params?: UtxoRequest): Promise<UtxoColumnarResponse>;
    /**
     * Fetch a single UTXO by its absolute index.
     *
     * Returns `null` if the UTXO does not exist (404).
     *
     * @param absoluteIndex - The global absolute index across all trees.
     */
    getUtxo(absoluteIndex: bigint): Promise<UtxoDataResponse | null>;
    /**
     * Fetch UTXOs scoped to a specific Merkle tree with pagination.
     *
     * @param treeIndex - The Merkle tree index.
     * @param params - Pagination params (cursor = absolute_index, limit optional).
     */
    getTreeUtxos(treeIndex: bigint, params?: {
        cursor?: bigint;
        limit?: bigint;
    }): Promise<UtxoResponse>;
    /**
     * Fetch all UTXO data with automatic pagination.
     *
     * Iterates through all pages starting from `start` up to an optional `end`.
     *
     * @param start - Starting absolute index (default: 0).
     * @param end - Optional ending absolute index (inclusive). Omit to fetch everything.
     * @param pageSize - Records per page (default: 1000, max: 5000).
     */
    getAllUtxoData(start?: bigint, end?: bigint, pageSize?: bigint): Promise<UtxoDataResponse[]>;
    protected get<T, P extends Message>(path: string, operation: string, protoSchema: GenMessage<P>, protoToJson: (proto: P) => T, extraHeaders?: Record<string, string>): Promise<T>;
    protected post<T, P extends Message>(path: string, operation: string, protoSchema: GenMessage<P>, protoToJson: (proto: P) => T, body: unknown): Promise<T>;
    protected handleResponse<T, P extends Message>(response: Response, operation: string, protoSchema: GenMessage<P>, protoToJson: (proto: P) => T): Promise<T>;
}

/**
 * Error class for Indexer Read Service client operations.
 */
declare class IndexerReadError extends Error {
    readonly operation: string;
    readonly statusCode: number | undefined;
    constructor(operation: string, message: string, statusCode?: number, cause?: Error);
}

export { type BasicHealthResponse, type BatchProofEntry, type BatchProofResponse, type DetailedHealthResponse, IndexerReadError, type LivenessResponse, type ProofRequest, type ProofResponse, ReadServiceClient, type ReadServiceClientConfig, type ReadinessResponse, type StatsResponse, type StorageHealth, type TreeInfoResponse, type UtxoColumnarColumns, type UtxoColumnarResponse, type UtxoDataResponse, type UtxoRequest, type UtxoResponse };
